import { secp256k1, schnorr } from '@noble/curves/secp256k1.js';
import { bigIntToBytes, bytesToBigInt, mod, modInv, toHex, fromHex, type Bytes } from './bytes';

/**
 * A thin, readable layer over @noble/curves' secp256k1.
 *
 * The game shows players the actual group elements and scalars, so this module
 * names things the way the BIPs do: G, n, x-only keys, lift_x, tagged hashes.
 */

export const Point = secp256k1.Point;
export type Pt = InstanceType<typeof secp256k1.Point>;

export const G: Pt = Point.BASE;
/** Order of the group generated by G. */
export const N: bigint = Point.Fn.ORDER;
/** Field prime of the curve y^2 = x^3 + 7. */
export const P_FIELD: bigint = Point.Fp.ORDER;

export const modN = (a: bigint): bigint => mod(a, N);
export const invN = (a: bigint): bigint => modInv(a, N);

export function mul(k: bigint, P: Pt = G): Pt {
  const kk = modN(k);
  return kk === 0n ? Point.ZERO : P.multiply(kk);
}

export const add = (a: Pt, b: Pt): Pt => a.add(b);
export const sub = (a: Pt, b: Pt): Pt => a.subtract(b);
export const neg = (a: Pt): Pt => a.negate();

export function hasEvenY(P: Pt): boolean {
  return P.toAffine().y % 2n === 0n;
}

/** 32-byte x coordinate, the BIP340 "x-only" public key encoding. */
export function xOnly(P: Pt): Bytes {
  return bigIntToBytes(P.toAffine().x, 32);
}

export const xOnlyHex = (P: Pt): string => toHex(xOnly(P));

/** 33-byte compressed SEC encoding (used by BIP327 KeyAgg and BIP32). */
export function compressed(P: Pt): Bytes {
  return P.toBytes(true);
}

/** BIP340 lift_x: the unique point with this x coordinate and even y. */
export function liftX(x: Bytes | bigint): Pt {
  const xb = typeof x === 'bigint' ? x : bytesToBigInt(x);
  return schnorr.utils.lift_x(xb);
}

export function pointFromHex(h: string): Pt {
  const b = fromHex(h);
  return b.length === 32 ? liftX(b) : Point.fromBytes(b);
}

/** hash_tag(x) = SHA256(SHA256(tag) || SHA256(tag) || x), BIP340 tagged hash. */
export function taggedHash(tag: string, ...msgs: Bytes[]): Bytes {
  return schnorr.utils.taggedHash(tag, ...msgs);
}

export const scalarToHex = (k: bigint): string => toHex(bigIntToBytes(modN(k), 32));
export const scalarBytes = (k: bigint): Bytes => bigIntToBytes(modN(k), 32);

export function pointLabel(P: Pt): string {
  if (P.is0()) return 'O (point at infinity)';
  const { x, y } = P.toAffine();
  return `(${x.toString(16).padStart(64, '0')}, ${y % 2n === 0n ? 'even' : 'odd'} y)`;
}

export { secp256k1, schnorr };
